// genRepo is a git repo with generated files of each kind, a file git ignores
// and an untracked file it does not.
func genRepo(t *testing.T) string {
	t.Helper()
	needRG(t)
	t.Setenv("ORCH_CACHE_DIR", t.TempDir())
	t.Setenv("ORCH_GOPLS", filepath.Join(t.TempDir(), "no-gopls"))
	t.Setenv("ORCH_TSLS", filepath.Join(t.TempDir(), "no-tsls"))
	t.Setenv("ORCH_JBCONTEXT", filepath.Join(t.TempDir(), "no-jbcontext"))
	code := evalOr(t.TempDir())
	writeTree(t, code, map[string]string{
		".gitignore":               "ignored/\n",
		".gitattributes":           "attr/** linguist-generated\nattr/keep.txt -linguist-generated\n",
		"go.mod":                   "module example.com/g\n\ngo 1.23\n",
		"src/real.ts":              "export const real = 'needleword'\n",
		"web/schema.d.ts":          "/* eslint-disable */\n/**\n * This file was auto-generated by openapi-typescript.\n */\nexport type A = 'needleword'\n",
		"gen/x.go":                 "package gen\n\nvar X = \"needleword\"\n",
		"attr/out.txt":             "needleword\n",
		"attr/keep.txt":            "needleword\n",
		"internal/db/store.sql.go": "// Code generated by sqlc. DO NOT EDIT.\n\npackage db\n\nfunc (q *Queries) CreateThing() {}\n\nfunc (q *Queries) Again() { q.CreateThing() }\n",
		"internal/app/use.go":      "package app\n\nfunc Use(q *db.Queries) { q.CreateThing() }\n",
		"internal/app/other.go":    "package app\n\nvar Note = \"needleword\"\n",
		"ignored/secret.go":        "package ignored\n\nvar Secret = \"needleword\"\n\nfunc SecretFunc() {}\n",
	})
	for _, args := range [][]string{{"init", "-q", "-b", "main"}, {"add", "."}, {"-c", "user.name=t", "-c", "user.email=t@e.com", "commit", "-q", "-m", "i"}} {
		cmd := exec.Command("git", args...)
		cmd.Dir = code
		if out, err := cmd.CombinedOutput(); err != nil {
			t.Fatalf("git %v: %v\n%s", args, err, out)
		}
	}
	writeTree(t, code, map[string]string{"fresh/new.go": "package fresh\n\nvar N = \"needleword\"\n"}) // untracked, not ignored
	return code
}

func TestOneFunctionDecidesWhatIsGenerated(t *testing.T) {
	code := genRepo(t)
	e := newCtxEnv(code, ctxOpts{})
	for p, want := range map[string]bool{
		"web/schema.d.ts": true, "internal/db/store.sql.go": true, "gen/x.go": true, "attr/out.txt": true,
		"attr/keep.txt": false, "src/real.ts": false, "internal/app/use.go": false,
	} {
		if got := e.isGenerated(p); got != want {
			t.Errorf("isGenerated(%s) = %v, want %v", p, got, want)
		}
	}
	if len(e.genCache) == 0 {
		t.Error("header checks were not cached")
	}
	for i, h := range []string{"Code generated by go-bindata. DO NOT EDIT.", "// @generated", "# autogenerated by x", "// auto-generated", "/* This file was generated by x */", "// DO NOT EDIT"} {
		p := filepath.Join(code, "h", "f"+string(rune('a'+i)))
		os.MkdirAll(filepath.Dir(p), 0o755)
		os.WriteFile(p, []byte("package x\n"+h+"\n"), 0o644)
		if !e.isGenerated("h/f" + string(rune('a'+i))) {
			t.Errorf("header %q was not recognized", h)
		}
	}
	late := filepath.Join(code, "h", "late.go")
	os.WriteFile(late, []byte("a\nb\nc\nd\ne\n// DO NOT EDIT\n"), 0o644)
	if e.isGenerated("h/late.go") {
		t.Error("a marker past the first lines counted")
	}
}

func TestGeneratedFilesAreHiddenCountedAndOptIn(t *testing.T) {
	code := genRepo(t)
	e := newCtxEnv(code, ctxOpts{})
	show := func(mode string) string {
		var sb strings.Builder
		v := e.textLookup(ctxLookup{Kind: "text", Query: "needleword", Gen: mode, Tests: "include"}, ctxFmt{})
		v.write(&sb, ctxFmt{}, nil, 0, 0)
		return sb.String()
	}
	def := show("")
	wantContains(t, def, "src/real.ts", "internal/app/other.go", "fresh/new.go", "(+3 in generated; --generated include|only)", "text: 4 of 4 matches")
	for _, bad := range []string{"web/schema.d.ts", "gen/x.go", "attr/out.txt", "ignored/secret.go"} {
		if strings.Contains(def, bad) {
			t.Errorf("default text listed %s:\n%s", bad, def)
		}
	}
	wantContains(t, def, "attr/keep.txt")
	inc := show("include")
	wantContains(t, inc, "web/schema.d.ts", "gen/x.go", "attr/out.txt", "src/real.ts")
	only := show("only")
	wantContains(t, only, "web/schema.d.ts", "attr/out.txt")
	if strings.Contains(only, "src/real.ts") {
		t.Errorf("--generated only listed hand-written code:\n%s", only)
	}
	for m, out := range map[string]string{"default": def, "include": inc, "only": only} {
		if strings.Contains(out, "ignored/secret.go") {
			t.Errorf("mode %q returned a gitignored file", m)
		}
	}
	// the totals of a page exclude what is hidden
	v := e.textLookup(ctxLookup{Kind: "text", Query: "needleword", Tests: "include", Limit: 2}, ctxFmt{})
	if v.Total != 4 || v.HiddenG != 3 || v.Pager == "" {
		t.Errorf("total %d hidden %d pager %q", v.Total, v.HiddenG, v.Pager)
	}
	if err := (&ctxLookup{Kind: "text", Query: "x", Gen: "maybe"}).validate(); err == nil {
		t.Error("a bad generated value was accepted")
	}
	if l, err := parseInlineLookup("text:needleword generated=only"); err != nil || l.Gen != "only" {
		t.Errorf("inline generated: %+v %v", l, err)
	}
}

func TestADefinitionInAGeneratedFileIsShownLabelledButNeverAsACaller(t *testing.T) {
	code := genRepo(t)
	e := newCtxEnv(code, ctxOpts{})
	f := e.Sym("CreateThing")
	if len(f.Defs) != 1 || f.Defs[0].Where != "internal/db/store.sql.go:5" {
		t.Fatalf("definition: %+v", f.Defs)
	}
	var sb strings.Builder
	e.symView(f, defaultSymOpts(ctxFmt{})).write(&sb, ctxFmt{}, nil, 0, 0)
	out := sb.String()
	wantContains(t, out, "CreateThing  ", "internal/db/store.sql.go:5", "  generated", "at least 1 non-test name matches (by name, not a call graph)", "+1 in generated", "internal/app/use.go")
	if strings.Contains(out, "store.sql.go:7") {
		t.Errorf("a generated file was listed as a caller:\n%s", out)
	}
	o := defaultSymOpts(ctxFmt{})
	o.Generated = "include"
	sb.Reset()
	e.symView(f, o).write(&sb, ctxFmt{}, nil, 0, 0)
	wantContains(t, sb.String(), "at least 2 non-test name matches", "store.sql.go")
}

func TestGeneratedFilesAreNeverLookAlikes(t *testing.T) {
	code := genRepo(t)
	writeTree(t, code, map[string]string{
		"internal/db/adapter.go": "// Code generated by adaptergen. DO NOT EDIT.\npackage db\n\nfunc CreateThing() {}\n",
	})
	e := newCtxEnv(code, ctxOpts{})
	text := "Build a thing. See `CreateThing` and `SecretFunc`.\n"
	br := e.Briefs([]briefInput{{ID: "x", Text: text, Owns: []string{"mine/"}}})[0]
	all := strings.Join(append(append([]string{}, br.Files...), br.Like...), "\n")
	if !strings.Contains(all, "internal/app/use.go") {
		t.Errorf("hand-written file missing from the brief:\n%s", all)
	}
	if strings.Contains(all, "store.sql.go") || strings.Contains(all, "adapter.go") || strings.Contains(all, "ignored/") {
		t.Errorf("a generated or ignored file reached the brief:\n%s", all)
	}
}

func TestIgnoredFilesNeverReachAnyCtxPath(t *testing.T) {
	code := genRepo(t)
	e := newCtxEnv(code, ctxOpts{})
	files := strings.Join(e.files(), "\n")
	if strings.Contains(files, "ignored/") || !strings.Contains(files, "fresh/new.go") {
		t.Errorf("file list:\n%s", files)
	}
	if tf := strings.Join(trackedFiles(code), "\n"); strings.Contains(tf, "ignored/") || !strings.Contains(tf, "fresh/new.go") {
		t.Errorf("trackedFiles:\n%s", tf)
	}
	if f := e.Sym("SecretFunc"); len(f.Defs) != 0 {
		t.Errorf("an ignored definition was found: %+v", f.Defs)
	}
	if got := e.ignoredPaths([]string{"ignored/secret.go", "src/real.ts"}); !got["ignored/secret.go"] || got["src/real.ts"] {
		t.Errorf("check-ignore: %v", got)
	}
}

func TestFindDropsIgnoredHitsAndHidesGeneratedOnes(t *testing.T) {
	c := newCtxHarness(t)
	writeTree(t, c.repo, map[string]string{
		".gitignore":      "ignored/\n",
		"web/schema.d.ts": "// This file was auto-generated by openapi-typescript\nexport type T = 1\n",
		"ignored/x.go":    "package ignored\n",
	})
	c.git("add", ".")
	c.git("commit", "-q", "-m", "gen")
	out, _ := exec.Command("git", "-C", c.repo, "rev-parse", "HEAD").Output()
	head := strings.TrimSpace(string(out))
	os.WriteFile(filepath.Join(c.jbDir, "rev"), []byte(head), 0o644)
	jb := filepath.Join(c.jbDir, "jbcontext")
	os.WriteFile(jb, []byte(`#!/bin/sh
case "$1" in
status) echo '{"type":"status_result","indices":[{"snapshots":[{"revision":"`+head+`","createdAt":1}]}]}';;
watch) printf 'Watch daemon running (pid 7)\n';;
search) cat <<'EOF'
{"type":"search_result","results":[
{"result":{"sourcePosition":{"relativePath":"pay/pay.go"}},"content":"package pay","contentStartLine":1},
{"result":{"sourcePosition":{"relativePath":"web/schema.d.ts"}},"content":"export type T = 1","contentStartLine":2},
{"result":{"sourcePosition":{"relativePath":"ignored/x.go"}},"content":"package ignored","contentStartLine":1}]}
EOF
;;
esac
`), 0o755)
	def := c.must("ctx", "find", "anything")
	wantContains(t, def, "pay/pay.go")
	result := decodedOutput(t, []byte(def), outputAgent).(map[string]any)["result"].(map[string]any)
	if result["in_generated"] != float64(1) {
		t.Fatalf("generated exclusion count changed: %#v", result)
	}
	if strings.Contains(def, "schema.d.ts") || strings.Contains(def, "ignored/x.go") {
		t.Errorf("default find:\n%s", def)
	}
	inc := c.must("ctx", "find", "anything", "--generated", "include")
	if !strings.Contains(inc, "web/schema.d.ts") || strings.Contains(inc, "ignored/x.go") {
		t.Errorf("--generated include:\n%s", inc)
	}
	only := c.must("ctx", "find", "anything", "--generated", "only")
	if !strings.Contains(only, "web/schema.d.ts") || strings.Contains(only, "pay/pay.go") {
		t.Errorf("--generated only:\n%s", only)
	}
	if code, out := c.run("ctx", "find", "x", "--generated", "maybe"); code != 2 || !strings.Contains(out, "valid values: none, include, only") {
		t.Errorf("a bad value: %d %s", code, out)
	}
	wantContains(t, c.must("ctx", "batch", "-q", "find:anything generated=only"), "web/schema.d.ts")
}

func TestConceptTipForNounListsAndWeakAnswers(t *testing.T) {
	for _, c := range []struct {
		q    string
		hits int
		want bool
	}{
		{"authentication", 5, true},
		{"upload service controller queue", 5, true},
		{"refund retry policy", 3, true},
		{"Code that checks a user's credentials and establishes a signed-in session.", 0, false},
		{"code that sends refunds", 0, false},
		{"checks credentials", 4, false},
		{"where the webhook signature is validated for every incoming call", 1, false},
		{"webhook validation", 1, true},
		{"sends a receipt after payment when it settles", 0, false},
		{"stripe webhooks", 0, true},
		{"", 0, false},
	} {
		if got := conceptTip(c.q, c.hits); got != c.want {
			t.Errorf("conceptTip(%q, %d) = %v, want %v", c.q, c.hits, got, c.want)
		}
	}
}

func TestFindShowsTheTipOnceAndHelpCarriesTheGuide(t *testing.T) {
	c := newCtxHarness(t)
	out := c.must("ctx", "find", "checkout gateway")
	result := decodedOutput(t, []byte(out), outputAgent).(map[string]any)["result"].(map[string]any)
	if result["tip"] != conceptTipText {
		t.Fatalf("missing concept guide: %#v", result)
	}
	if strings.Contains(c.must("ctx", "find", "Code that starts a hosted checkout session for an invoice"), "tip:") {
		t.Error("the tip was shown for a sentence")
	}
	batch := c.must("ctx", "batch", "-q", "find:checkout gateway", "-q", "find:payment gateway", "-q", "text:StartCheckout")
	decoded := decodedOutput(t, []byte(batch), outputAgent)
	if n := strings.Count(fmt.Sprint(decoded), conceptTipText); n != 1 {
		t.Errorf("tip shown %d times in a batch:\n%s", n, batch)
	}
	help := c.must("ctx", "find", "--help")
	wantContains(t, help, "search one behavior at a time in plain language", "Code that <action> on <entity>, when <trigger>, producing <result>", "Weak: `authentication`", "Better: `Code that checks a user's credentials")
	helpInfo := decodedOutput(t, []byte(help), outputAgent).(map[string]any)
	if guide, ok := helpInfo["query_guide"].(string); !ok || !strings.HasPrefix(guide, "guide:") {
		t.Errorf("the help omits its dedicated query guide:\n%s", help)
	}
	wantContains(t, c.must("ctx"), "describe one behavior in plain language")
}
